function n(t){return t===0?0:t}function r(t){const e=n(t);return`${e<0?"-":""}$${(Math.abs(e)/100).toFixed(2)}`}function a(t){return`៛ ${n(t).toLocaleString("en-US")}`}function i(t){return t?t.slice(0,16).replace("T"," "):"—"}function o(t){return t?t.slice(0,10):"—"}function c(t){return t.split(/\s+/).filter(Boolean).map(e=>e[0]).join("").slice(0,2).toUpperCase()||"?"}export{r as a,i as b,o as c,a as f,c as i};
